from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from .catalog import exact_sku_confidence, midpoint_price
from .evidence import board_memory_evidence, memory_basis, performance_evidence, verified_memory_gb
from .reports import published_power_boundary
from .scoring import catalog_score


def _float_or_none(value: Any) -> float | None:
    if value is None:
        return None
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def _rows(parts: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Build the dashboard view model without collapsing evidence boundaries."""
    rows: list[dict[str, Any]] = []
    for part in parts:
        power, power_scope = published_power_boundary(part)
        memory_value, memory_basis_label, memory_confidence = memory_basis(part)
        board_memory = board_memory_evidence(part)
        perf = performance_evidence(part)
        dimensions = part.get("dimensions_mm") or {}
        rows.append({
            "id": str(part.get("id", "")),
            "name": str(part.get("name", "")),
            "vendor": str(part.get("vendor", "")),
            "category": str(part.get("category", "")),
            "hardware_class": str(part.get("hardware_class", "")),
            "accelerator_family": str(part.get("accelerator_family", "")),
            "accelerator": str(part.get("accelerator", "")),
            "form_factor": str(part.get("form_factor", "")),
            "price": midpoint_price(part),
            "price_min": _float_or_none(part.get("price_min_usd")),
            "price_max": _float_or_none(part.get("price_max_usd")),
            "price_status": str(part.get("price_status", "unknown")),
            "moq": int(part.get("moq", 1) or 1),
            "memory": verified_memory_gb(part),
            "memory_planning": memory_value,
            "memory_basis": memory_basis_label,
            "memory_confidence": memory_confidence,
            "memory_config_status": str(part.get("memory_config_status", "unknown")),
            "installed_memory": _float_or_none(part.get("memory_capacity_gb")),
            "board_max_memory": _float_or_none(part.get("max_memory_gb")),
            "board_memory_basis": str(board_memory.get("basis", "unknown")),
            "board_memory_source_url": str(board_memory.get("source_url", "")),
            "board_memory_verified_on": str(board_memory.get("verified_on", "")),
            "cpu_max_memory": _float_or_none(part.get("cpu_max_memory_gb")),
            "power": power,
            "power_scope": power_scope,
            "power_target": _float_or_none(part.get("power_target_w")),
            "power_max": _float_or_none(part.get("power_max_w")),
            "score": catalog_score(part),
            "risk": str(part.get("risk_level", "unknown")),
            "lifecycle": str(part.get("lifecycle_status", "unknown")),
            "listing_status": str(part.get("listing_status", "unknown")),
            "llm_candidate": bool(part.get("llm_candidate", part.get("category") == "compute_node")),
            "llm_support": str(part.get("llm_support", "unknown")),
            "workload_role": str(part.get("workload_role", "")),
            "software_maturity": str(part.get("software_maturity", "unknown")),
            "software_stack": str(part.get("software_stack", "")),
            "host_mode": str(part.get("host_mode", "")),
            "host_requirements": str(part.get("host_requirements", "")),
            "dc_input_v": _float_or_none(part.get("dc_input_v")),
            "dc_input_min_v": _float_or_none(part.get("dc_input_min_v")),
            "dc_input_max_v": _float_or_none(part.get("dc_input_max_v")),
            "dc_connector": str(part.get("dc_connector", "")),
            "psu_requirements": str(part.get("psu_requirements", "")),
            "cooling_requirements": str(part.get("cooling_requirements", "")),
            "dimensions": {
                "width_mm": _float_or_none(dimensions.get("width_mm")),
                "depth_mm": _float_or_none(dimensions.get("depth_mm")),
                "height_mm": _float_or_none(dimensions.get("height_mm")),
            },
            "source_confidence": _float_or_none(part.get("source_confidence")),
            "seller_confidence": _float_or_none(part.get("seller_confidence")),
            "sku_confidence": exact_sku_confidence(part),
            "performance_source": perf["source_type"],
            "performance_confidence": perf["confidence"],
            "performance_source_url": perf["source_url"],
            "performance_notes": perf["notes"],
            "plain_language": str(part.get("plain_language", "")),
            "source_notes": str(part.get("source_notes", "")),
            "url": str(part.get("url", "")),
            "source_url": str(part.get("source_url", part.get("url", ""))),
            "verified_on": str(part.get("verified_on", "")),
        })
    return rows


