def render_catalog_dashboard(parts: list[dict[str, Any]], output: Path | str) -> Path:
    """Render a self-contained, responsive catalog research dashboard."""
    output = Path(output)
    output.parent.mkdir(parents=True, exist_ok=True)
    payload = json.dumps(_rows(parts), separators=(",", ":"), ensure_ascii=False).replace("</", "<\\/")
    output.write_text(_DASHBOARD_HTML.replace("__CATALOG_DATA__", payload), encoding="utf-8")
    return output
